generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCashFlow ?avgProgress WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?avgProgress) WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?progress)) < 50)
  }
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}
ORDER BY DESC(?totalCashFlow)
LIMIT 10

